const test = require("node:test");
const assert = require("node:assert");

const { backoffDelay } = require("./retry");

test("upper bound is the cap", () => {
  const delay = backoffDelay(2, 1, 100, () => 1.0);
  assert.strictEqual(delay, 4);
});

test("lower bound is zero", () => {
  const delay = backoffDelay(5, 1, 100, () => 0.0);
  assert.strictEqual(delay, 0);
});

test("delay never exceeds maxDelay for large attempts", () => {
  const delay = backoffDelay(50, 1, 10, () => 1.0);
  assert.strictEqual(delay, 10);
});

test("default rand stays in bounds", () => {
  for (let attempt = 0; attempt < 10; attempt++) {
    const delay = backoffDelay(attempt, 1, 20);
    assert.ok(delay >= 0 && delay <= 20);
  }
});

reference_solution.retry.js:
function backoffDelay(attempt, base, maxDelay, rand = Math.random) {
  const cap = Math.min(maxDelay, base * 2 ** attempt);
  return rand() * cap;
}

module.exports = { backoffDelay };

